import{_ as e,c as o,o as a,V as s}from"./chunks/framework.5a924dd5.js";const m=JSON.parse('{"title":"Upgrading to tsoa 7","description":"","frontmatter":{"title":"Upgrading to tsoa 7","lang":"en-US"},"headers":[],"relativePath":"upgrading-to-v7.md","filePath":"upgrading-to-v7.md"}'),t={name:"upgrading-to-v7.md"},r=s(`<h1 id="upgrading-to-tsoa-7" tabindex="-1">Upgrading to tsoa 7 <a class="header-anchor" href="#upgrading-to-tsoa-7" aria-label="Permalink to &quot;Upgrading to tsoa 7&quot;">​</a></h1><p>This guide compares tsoa 7 with tsoa 6.6.0, the last 6.x release on npm.</p><p><strong>What we will talk about:</strong></p><nav class="table-of-contents"><ul><li><a href="#checklist">Checklist</a></li><li><a href="#requirements">Requirements</a></li><li><a href="#packages-and-imports">Packages and imports</a><ul><li><a href="#install-your-framework-packages-yourself">Install your framework packages yourself</a></li><li><a href="#import-template-services-from-a-subpath">Import template services from a subpath</a></li><li><a href="#code-that-uses-tsoa-s-internals">Code that uses tsoa&#39;s internals</a></li></ul></li><li><a href="#configuration">Configuration</a><ul><li><a href="#multeropts-is-removed">multerOpts is removed</a></li><li><a href="#tsoa-reads-your-tsconfig-json">tsoa reads your tsconfig.json</a></li><li><a href="#typescript-6-defaults">TypeScript 6 defaults</a></li><li><a href="#spec-version">Spec version</a></li></ul></li><li><a href="#spec-generation">Spec generation</a><ul><li><a href="#type-resolution-uses-the-typescript-checker">Type resolution uses the TypeScript checker</a></li><li><a href="#discriminated-unions">Discriminated unions</a></li><li><a href="#pattern">@pattern</a></li><li><a href="#other-spec-changes">Other spec changes</a></li></ul></li><li><a href="#validation">Validation</a></li><li><a href="#express-responses">Express responses</a></li><li><a href="#security">Security</a></li><li><a href="#new-features">New features</a><ul><li><a href="#openapi-3-1">OpenAPI 3.1</a></li><li><a href="#optional-authentication">Optional authentication</a></li><li><a href="#raw-binary-request-bodies">Raw binary request bodies</a></li><li><a href="#other-additions">Other additions</a></li></ul></li></ul></nav><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ol><li><a href="#install-your-framework-packages-yourself">Install the packages for your framework</a>.</li><li>Replace imports of <code>ExpressTemplateService</code>, <code>HapiTemplateService</code> or <code>KoaTemplateService</code> <a href="#import-template-services-from-a-subpath">with their subpaths</a>.</li><li>Remove <code>multerOpts</code> from <code>tsoa.json</code> and <a href="#multeropts-is-removed">pass a multer instance</a>.</li><li>Regenerate your routes and your spec, then compare the spec with the old one. Most changes come from <a href="#tsoa-reads-your-tsconfig-json">the tsconfig.json tsoa now reads</a>.</li><li>Read <a href="#validation">Validation</a> and <a href="#express-responses">Responses</a> if clients depend on exact error messages or response bodies.</li></ol><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>TypeScript 5.7 or later, or TypeScript 6.</li><li>Express 4 or 5, Koa with <code>@types/koa</code> 2 or 3, or Hapi 21.</li><li>The test suite runs on Node.js 22, 24 and 26.</li></ul><h2 id="packages-and-imports" tabindex="-1">Packages and imports <a class="header-anchor" href="#packages-and-imports" aria-label="Permalink to &quot;Packages and imports&quot;">​</a></h2><h3 id="install-your-framework-packages-yourself" tabindex="-1">Install your framework packages yourself <a class="header-anchor" href="#install-your-framework-packages-yourself" aria-label="Permalink to &quot;Install your framework packages yourself&quot;">​</a></h3><p><code>@tsoa/runtime</code> used to depend on Express, Hapi, <code>@hapi/boom</code> and <code>@types/koa</code>, so every project installed all three frameworks. They are now optional peer dependencies. Install the ones for your framework:</p><table><thead><tr><th>Framework</th><th>Packages</th></tr></thead><tbody><tr><td>Express</td><td><code>express</code>, <code>@types/express</code> (4 or 5)</td></tr><tr><td>Koa</td><td><code>koa</code>, <code>@types/koa</code> (2 or 3)</td></tr><tr><td>Hapi</td><td><code>@hapi/hapi</code>, <code>@hapi/boom</code></td></tr></tbody></table><p>Hapi projects must list <code>@hapi/boom</code> in their own <code>package.json</code>, because the generated routes import it.</p><p><code>@tsoa/runtime</code> and <code>@tsoa/cli</code> no longer depend on <code>@types/multer</code>. If your code uses <code>Express.Multer.File</code>, install it yourself:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">yarn</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">add</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">-D</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">@types/multer</span></span></code></pre></div><p>With TypeScript 6, or with <code>types</code> set in your <code>tsconfig.json</code>, also list <code>multer</code> there, because TypeScript only loads the global <code>Express.Multer</code> types from packages it includes.</p><p>See <a href="./frameworks.html">Framework packages</a>.</p><h3 id="import-template-services-from-a-subpath" tabindex="-1">Import template services from a subpath <a class="header-anchor" href="#import-template-services-from-a-subpath" aria-label="Permalink to &quot;Import template services from a subpath&quot;">​</a></h3><p><code>@tsoa/runtime</code> and <code>tsoa</code> no longer export <code>ExpressTemplateService</code>, <code>HapiTemplateService</code> or <code>KoaTemplateService</code>. Custom route templates and classes that extend a template service import them from the framework&#39;s subpath:</p><div class="language-diff"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">-</span><span style="color:#F07178;"> import { ExpressTemplateService } from &#39;@tsoa/runtime&#39;;</span></span>
<span class="line"><span style="color:#89DDFF;">+</span><span style="color:#C3E88D;"> import { ExpressTemplateService } from &#39;@tsoa/runtime/express&#39;;</span></span></code></pre></div><p>The same applies to <code>@tsoa/runtime/hapi</code> and <code>@tsoa/runtime/koa</code>. The generated routes import from the new subpaths, so regenerate them.</p><p><code>@tsoa/runtime</code> now has an <code>exports</code> map. Deep imports work only under <code>@tsoa/runtime/dist/...</code>.</p><h3 id="code-that-uses-tsoa-s-internals" tabindex="-1">Code that uses tsoa&#39;s internals <a class="header-anchor" href="#code-that-uses-tsoa-s-internals" aria-label="Permalink to &quot;Code that uses tsoa&#39;s internals&quot;">​</a></h3><p>These changes affect only code that extends tsoa or imports its internal files:</p><ul><li><code>@tsoa/cli</code> no longer has <code>metadataGeneration/typeResolver</code> or <code>metadataGeneration/transformer/*</code>. Use <code>MetadataGenerator.resolveType</code> and <code>MetadataGenerator.resolveTypeNode</code>.</li><li>The <code>Swagger</code> namespace changed. <code>Swagger.Schema</code> and <code>Swagger.Parameter</code> are removed; use <code>Swagger.Schema2</code>, <code>Swagger.Schema3</code>, <code>Swagger.Schema31</code>, <code>Swagger.Parameter2</code> or <code>Swagger.Parameter3</code>. <code>Swagger.Spec3</code> is now <code>Spec30 | Spec31</code>. <code>Swagger.Header3</code> no longer has <code>type</code> and <code>format</code>; set them on its <code>schema</code>. <code>discriminator</code> is a string in <code>Schema2</code> and an object in <code>Schema3</code>.</li><li><code>Tsoa.Type</code> has a new member, <code>Tsoa.TupleType</code>. A <code>switch</code> that checks every <code>dataType</code> needs a <code>&#39;tuple&#39;</code> case.</li><li><code>ValidationService.validateBuffer</code> now takes <code>(name, value, fieldErrors, parent)</code> and reports a field error instead of throwing.</li><li>The generated route templates changed. If you keep a copy as <code>routes.middlewareTemplate</code>, start again from the new template.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="multeropts-is-removed" tabindex="-1"><code>multerOpts</code> is removed <a class="header-anchor" href="#multeropts-is-removed" aria-label="Permalink to &quot;\`multerOpts\` is removed&quot;">​</a></h3><p><code>multerOpts</code> was deprecated in 6.4.0. Remove it from <code>tsoa.json</code> and pass a multer instance to the generated routes:</p><div class="language-diff"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">// tsoa.json</span></span>
<span class="line"><span style="color:#A6ACCD;">  &quot;routes&quot;: {</span></span>
<span class="line"><span style="color:#89DDFF;">-</span><span style="color:#F07178;">   &quot;multerOpts&quot;: { &quot;dest&quot;: &quot;/tmp&quot; }</span></span>
<span class="line"><span style="color:#A6ACCD;">  }</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#A6ACCD;"> multer </span><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">multer</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#82AAFF;">RegisterRoutes</span><span style="color:#A6ACCD;">(app</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span><span style="color:#A6ACCD;"> </span><span style="color:#F07178;">multer</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">multer</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">{</span><span style="color:#A6ACCD;"> </span><span style="color:#F07178;">dest</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/tmp</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">) </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span></code></pre></div><p>tsoa 7 ignores <code>multerOpts</code> without a warning. Without an instance, the routes use a default one limited to 8 MB per file.</p><h3 id="tsoa-reads-your-tsconfig-json" tabindex="-1">tsoa reads your tsconfig.json <a class="header-anchor" href="#tsoa-reads-your-tsconfig-json" aria-label="Permalink to &quot;tsoa reads your tsconfig.json&quot;">​</a></h3><p>tsoa 6 compiled your controllers with only the <code>compilerOptions</code> from <code>tsoa.json</code>. tsoa 7 reads the nearest <code>tsconfig.json</code>, searching up from the directory you run tsoa in, and applies <code>tsoa.json</code>&#39;s <code>compilerOptions</code> on top. <code>paths</code>, <code>moduleResolution</code>, <code>customConditions</code> and the strict flags now take effect.</p><p>This can change your spec:</p><ul><li>With <code>strict</code> or <code>strictNullChecks</code> on, tsoa keeps <code>null</code> and <code>undefined</code> that tsoa 6 dropped inside mapped types. For example, a <code>string | null</code> property of <code>Partial&lt;T&gt;</code> is now <code>nullable</code>.</li><li>An invalid <code>tsconfig.json</code> now stops generation with TypeScript&#39;s error.</li></ul><p>To keep tsoa 6&#39;s output, set <code>&quot;compilerOptions&quot;: { &quot;strictNullChecks&quot;: false }</code> in <code>tsoa.json</code>.</p><h3 id="typescript-6-defaults" tabindex="-1">TypeScript 6 defaults <a class="header-anchor" href="#typescript-6-defaults" aria-label="Permalink to &quot;TypeScript 6 defaults&quot;">​</a></h3><p>On TypeScript 6:</p><ul><li><code>types</code> defaults to none instead of every package under <code>node_modules/@types</code>. If a model uses a global type that nothing imports, list its package in <code>compilerOptions.types</code>.</li><li>A model that extends <code>Error</code> gains an optional <code>cause</code> property from TypeScript 6&#39;s default lib.</li></ul><h3 id="spec-version" tabindex="-1">Spec version <a class="header-anchor" href="#spec-version" aria-label="Permalink to &quot;Spec version&quot;">​</a></h3><p>The <code>tsoa</code> CLI still generates Swagger 2.0 when <code>spec.specVersion</code> is not set. A direct call to <code>generateSpec()</code> without <code>specVersion</code> now generates OpenAPI 3.1 instead of Swagger 2.0. Set <code>specVersion</code> to keep the output you have.</p><h2 id="spec-generation" tabindex="-1">Spec generation <a class="header-anchor" href="#spec-generation" aria-label="Permalink to &quot;Spec generation&quot;">​</a></h2><h3 id="type-resolution-uses-the-typescript-checker" tabindex="-1">Type resolution uses the TypeScript checker <a class="header-anchor" href="#type-resolution-uses-the-typescript-checker" aria-label="Permalink to &quot;Type resolution uses the TypeScript checker&quot;">​</a></h3><p>tsoa now takes each type from the TypeScript checker instead of rebuilding it from the source text. Specs for written types such as interfaces, aliases, generics, <code>Pick</code>, <code>Omit</code>, <code>Partial</code>, <code>Record</code> and enums do not change. These do:</p><ul><li><strong>Component names of type arguments tsoa could not name.</strong> Template literal types, tuples and other types tsoa 6 named <code>any</code> now get their own names. <code>Box&lt;[string, number]&gt;</code> becomes <code>Box__string.number__</code>. This changes those <code>$ref</code>s and the names in clients generated from your spec.</li><li><strong>Objects from TypeScript&#39;s own libraries.</strong> A class or interface declared only in TypeScript&#39;s libraries must have a supported mapping or a <code>toJSON</code> method. <code>Set</code>, <code>Map</code>, <code>RegExp</code>, typed arrays, <code>WeakRef</code>, <code>PropertyDescriptor</code> and error subtypes such as <code>TypeError</code> fail generation. tsoa 6 failed on most of them as well, with a less useful message. <code>Date</code>, <code>Buffer</code>, <code>Error</code>, and models with <code>toJSON</code> such as <code>URL</code> still work.</li><li><strong>Inferred object types.</strong> For a type tsoa infers from a value, such as a method without a return type that returns <code>{ count: 1 }</code>, or <code>typeof someConstant</code>, tsoa 7 marks each property as optional with the value as its <code>default</code>. tsoa 6 marked them as required. Write the return type to keep them required.</li><li><strong>Error messages</strong> for a return type end with <code>in &#39;Controller.method&#39; return type</code>.</li></ul><p>Several types now generate where tsoa 6 failed: tuples (OpenAPI 3.1 only), template literal types such as <code>\`user_\${string}\`</code>, <code>typeof value</code>, indexed access such as <code>Params[Kind.A]</code>, <code>Uppercase&lt;&#39;a&#39; | &#39;b&#39;&gt;</code>, <code>DeepPartial&lt;T&gt;</code>-style recursive mapped types, and models that reference each other while inheriting.</p><h3 id="discriminated-unions" tabindex="-1">Discriminated unions <a class="header-anchor" href="#discriminated-unions" aria-label="Permalink to &quot;Discriminated unions&quot;">​</a></h3><p>In OpenAPI 3 and 3.1, a union of models that share one required string-literal property now generates <code>oneOf</code> with a <code>discriminator</code> instead of <code>anyOf</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#C792EA;">interface</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Cat</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">kind</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">cat</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">meows</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">boolean</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#C792EA;">interface</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Dog</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">kind</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">dog</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">barks</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">boolean</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#C792EA;">type</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Pet</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Cat</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">|</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Dog</span><span style="color:#89DDFF;">;</span></span></code></pre></div><p>Validation uses the tag to choose the member. See <a href="#validation">Validation</a>.</p><h3 id="pattern" tabindex="-1"><code>@pattern</code> <a class="header-anchor" href="#pattern" aria-label="Permalink to &quot;\`@pattern\`&quot;">​</a></h3><ul><li>An invalid regular expression in <code>@pattern</code> now stops generation. tsoa 6 wrote it to the spec as it was.</li><li>A pattern wrapped in single backticks may contain spaces: <code>@pattern \`^[a-z ]+$\` Letters and spaces</code>. tsoa 6 cut it at the first space.</li></ul><h3 id="other-spec-changes" tabindex="-1">Other spec changes <a class="header-anchor" href="#other-spec-changes" aria-label="Permalink to &quot;Other spec changes&quot;">​</a></h3><ul><li><code>@FormField()</code> takes its parameter&#39;s type. <code>@FormField() n: number</code> is now a number in the spec and in validation. tsoa 6 always used a string.</li><li><code>@Body() body: Readable</code> gets the raw request stream. Its spec is <code>application/octet-stream</code> with <code>format: binary</code>. tsoa 6 treated it as a JSON <code>byte</code> string.</li><li><code>@example 0</code>, <code>@example false</code> and <code>@example &quot;&quot;</code> now appear in the spec.</li><li><code>@deprecated</code> and <code>@example</code> on a type alias now appear in its schema.</li><li><code>@title</code> sets a schema&#39;s <code>title</code>.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Requests that tsoa 6 accepted may now fail:</p><ul><li><strong>Discriminated unions</strong> validate only the member the tag selects. An error names the failing field, such as <code>body.barks</code>, instead of a summary of every member. A missing or unknown tag gives one error on the tag property.</li><li><strong>Enums</strong> never match an array or an object: <code>[&quot;admin&quot;]</code> no longer matches <code>&quot;admin&quot;</code>. In a body, the string <code>&quot;1&quot;</code> matches the number <code>1</code>, or <code>&quot;true&quot;</code> matches <code>true</code>, only when <code>bodyCoercion</code> is on.</li><li><strong>Self-referencing models</strong> are checked at every depth.</li><li><strong><code>minItems</code> and <code>maxItems</code></strong> of 0 are enforced.</li><li><strong><code>Buffer</code></strong> accepts a string, a buffer, an array of bytes or the JSON form <code>{ &quot;type&quot;: &quot;Buffer&quot;, &quot;data&quot;: [...] }</code>. Any other value is a field error. tsoa 6 passed it to <code>Buffer.from</code>, which could allocate a buffer of any size from <code>{ &quot;length&quot;: n }</code> or throw a 500.</li><li><strong><code>T | null</code></strong> keeps <code>null</code>. tsoa 6 turned <code>null</code> into <code>false</code> for <code>boolean | null</code>.</li></ul><p>Error responses change too:</p><ul><li>Field errors for <code>@Body()</code> and <code>@BodyProp()</code> no longer include the rejected <code>value</code>, only the <code>message</code>.</li><li>Errors for unions and intersections are summarized and cut to 1000 characters, and the value they echo is cut to the same length.</li><li>The keys of errors inside arrays carry the full path, such as <code>body.children.$0.children.$0.name</code>. tsoa 6 dropped the part above the array.</li></ul><h2 id="express-responses" tabindex="-1">Express responses <a class="header-anchor" href="#express-responses" aria-label="Permalink to &quot;Express responses&quot;">​</a></h2><table><thead><tr><th>Controller returns</th><th>tsoa 6</th><th>tsoa 7</th></tr></thead><tbody><tr><td>a <code>Buffer</code> or <code>Uint8Array</code></td><td>JSON <code>{&quot;type&quot;:&quot;Buffer&quot;,&quot;data&quot;:[...]}</code></td><td>the bytes, as <code>application/octet-stream</code></td></tr><tr><td>a string, with <code>Content-Type: text/plain</code></td><td>the string as JSON, in quotes</td><td>the string as it is</td></tr><tr><td>a stream that fails before sending data</td><td>the Node process stops</td><td>the error goes to <code>next()</code> and your error handler</td></tr></tbody></table><p>Strings without a <code>Content-Type</code>, numbers, objects and <code>null</code> are sent as before.</p><p>An optional <code>@Body()</code> is <code>undefined</code> when the request has no body. tsoa 6 passed the <code>{}</code> that body-parser leaves. A required <code>@Body()</code> still gets <code>{}</code>.</p><p>If you move to Express 5 as well, read the <a href="./frameworks.html#express-5">Express 5 notes</a>.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>An empty entry in a route&#39;s security list now allows anonymous access (see <a href="#optional-authentication">Optional authentication</a>). So that no route opens by mistake, generation fails for two <code>@Security</code> decorators that tsoa 6 accepted:</p><ul><li><code>@Security({ api_key: makeScopes() })</code>, or any object whose scopes come from a function call. tsoa 6 generated an empty entry for it, <code>security: [{}]</code>.</li><li><code>@Security(&#39;__proto__&#39;)</code>.</li></ul><p>Other forms generate as before, including names and scopes held in constants.</p><h2 id="new-features" tabindex="-1">New features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New features&quot;">​</a></h2><h3 id="openapi-3-1" tabindex="-1">OpenAPI 3.1 <a class="header-anchor" href="#openapi-3-1" aria-label="Permalink to &quot;OpenAPI 3.1&quot;">​</a></h3><p>Set <code>&quot;specVersion&quot;: 3.1</code>. OpenAPI 3.1 describes tuples with <code>prefixItems</code>.</p><h3 id="optional-authentication" tabindex="-1">Optional authentication <a class="header-anchor" href="#optional-authentication" aria-label="Permalink to &quot;Optional authentication&quot;">​</a></h3><p><code>@Security({})</code> next to a scheme makes authentication optional:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">Security</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">bearerAuth</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;">)</span></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">Security</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">{}</span><span style="color:#A6ACCD;">)</span></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">Get</span><span style="color:#A6ACCD;">()</span></span>
<span class="line"><span style="color:#A6ACCD;">public async </span><span style="color:#82AAFF;">list</span><span style="color:#A6ACCD;">(@</span><span style="color:#82AAFF;">Request</span><span style="color:#A6ACCD;">() request: express</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">Request) </span><span style="color:#89DDFF;">{}</span></span></code></pre></div><p>A request without credentials continues with <code>request.user</code> undefined, provided your authentication function rejects with <code>MissingCredentialsError</code> (exported from <code>tsoa</code>) when the credentials are absent. Any other rejection, such as an invalid token, still refuses the request, with 401 by default.</p><h3 id="raw-binary-request-bodies" tabindex="-1">Raw binary request bodies <a class="header-anchor" href="#raw-binary-request-bodies" aria-label="Permalink to &quot;Raw binary request bodies&quot;">​</a></h3><p>A <code>@Body()</code> parameter typed as <code>Readable</code> from <code>stream</code> receives the request stream, without parsing or validation. Write the type as <code>Readable</code>; <code>stream.Readable</code>, aliases and unions are not recognized. Express and Koa reject the request if a body parser has already read the stream.</p><h3 id="other-additions" tabindex="-1">Other additions <a class="header-anchor" href="#other-additions" aria-label="Permalink to &quot;Other additions&quot;">​</a></h3><ul><li><code>@Queries()</code> accepts type aliases and nested object types.</li><li><code>spec.disableBasePathPrefixSlash</code> drops the <code>/</code> between the server URL and <code>basePath</code> (OpenAPI 3 and later).</li><li><code>425 Too Early</code> is a known status code.</li><li>Spread syntax works in values tsoa reads, such as <code>@Example({ ...base, id: 1 })</code>.</li><li>An empty <code>@returns</code> tag no longer stops generation.</li><li>The generated routes build their per-route data once instead of on every request.</li></ul>`,79),n=[r];function c(l,i,d,p,h,u){return a(),o("div",null,n)}const f=e(t,[["render",c]]);export{m as __pageData,f as default};
